from pathlib import Path

path = Path("main/tasks/power_management_task.cpp")
src = path.read_text()

include_anchor = '#define POLL_RATE 2000\n\nstatic const char *TAG = "power_management";'
include_replacement = '''#define POLL_RATE 2000\n\nstatic const char *TAG = "power_management";\n\n#ifdef NERDOCTAXEGAMMA\n// NerdOCTAXE-Gamma adaptive runtime governor.\n// The frequency configured in AxeOS is treated as the maximum ceiling.\n// Runtime changes are never written back to NVS.\nstatic int nerdOctaxeChipHardCap(float temp, int currentCap)\n{\n    struct Step { float trigger; int cap; };\n    static const Step steps[] = {\n        {70.0f, 675}, {72.0f, 650}, {74.0f, 625}, {76.0f, 600},\n        {78.0f, 575}, {80.0f, 550}, {82.0f, 525}\n    };\n\n    int requested = 0;\n    for (const auto &step : steps) {\n        if (temp >= step.trigger) requested = step.cap;\n    }\n\n    // Heating: lower the cap immediately.\n    if (currentCap == 0 || (requested != 0 && requested < currentCap)) {\n        return requested;\n    }\n\n    // Cooling: 2 C hysteresis before releasing the current cap.\n    if (currentCap != 0) {\n        float trigger = 70.0f;\n        for (const auto &step : steps) {\n            if (step.cap == currentCap) {\n                trigger = step.trigger;\n                break;\n            }\n        }\n        if (temp >= trigger - 2.0f) return currentCap;\n    }\n\n    requested = 0;\n    for (const auto &step : steps) {\n        if (temp >= step.trigger) requested = step.cap;\n    }\n    return requested;\n}\n\nstatic int nerdOctaxeVrHardCap(float temp, int currentCap)\n{\n    struct Step { float trigger; int cap; };\n    static const Step steps[] = {\n        {80.0f, 675}, {85.0f, 650}, {90.0f, 600}, {95.0f, 550}, {100.0f, 525}\n    };\n\n    int requested = 0;\n    for (const auto &step : steps) {\n        if (temp >= step.trigger) requested = step.cap;\n    }\n\n    if (currentCap == 0 || (requested != 0 && requested < currentCap)) {\n        return requested;\n    }\n\n    if (currentCap != 0) {\n        float trigger = 80.0f;\n        for (const auto &step : steps) {\n            if (step.cap == currentCap) {\n                trigger = step.trigger;\n                break;\n            }\n        }\n        if (temp >= trigger - 3.0f) return currentCap;\n    }\n\n    requested = 0;\n    for (const auto &step : steps) {\n        if (temp >= step.trigger) requested = step.cap;\n    }\n    return requested;\n}\n\nstatic int nerdOctaxeStepDown(int mhz)\n{\n    return std::max(525, mhz - 25);\n}\n\nstatic int nerdOctaxeStepUp(int mhz, int ceiling)\n{\n    return std::min(ceiling, mhz + 25);\n}\n#endif'''

if include_anchor not in src:
    raise SystemExit("Unable to find power-management include anchor; upstream changed")
src = src.replace(include_anchor, include_replacement, 1)

loop_anchor = '''        influx_task_set_temperature(m_chipTempMax, m_vrTemp);\n\n        // Run fan controller (reads RPM, drives fans, updates overheat flags)'''
loop_replacement = '''        influx_task_set_temperature(m_chipTempMax, m_vrTemp);\n\n#ifdef NERDOCTAXEGAMMA\n        // Adaptive AUTO mode. AxeOS configured MHz is the maximum ceiling.\n        // Target band is intentionally conservative: hold 66-69 C, step down\n        // after 6 s above 69 C, and recover one 25 MHz step only after 60 s\n        // at or below 66 C. Existing stock overheat shutdown remains untouched.\n        static int autoMHz = -1;\n        static int chipHardCapMHz = 0;\n        static int vrHardCapMHz = 0;\n        static int lastRuntimeMHz = -1;\n        static int lastConfiguredMHz = -1;\n        static int hotPolls = 0;\n        static int coolPolls = 0;\n        static int invalidChipPolls = 0;\n\n        const int configuredMHz = m_board->getAsicFrequency();\n        const bool configuredChanged = configuredMHz != lastConfiguredMHz;\n        const float vrMax = std::max(m_vrTemp, m_vrTempInt);\n        const bool chipTempValid = m_chipTempMax >= 10.0f && m_chipTempMax <= 110.0f;\n        const bool vrTempValid = vrMax > 0.0f && vrMax <= 125.0f;\n\n        if (autoMHz < 0) autoMHz = configuredMHz;\n\n        // Lowering the AxeOS setting takes effect immediately. Raising it only\n        // raises the ceiling; AUTO mode climbs slowly when sufficiently cool.\n        if (configuredChanged && configuredMHz < autoMHz) {\n            autoMHz = configuredMHz;\n        }\n\n        if (!chipTempValid) {\n            invalidChipPolls++;\n            hotPolls = 0;\n            coolPolls = 0;\n            // Three consecutive invalid readings (~6 s) -> safe minimum.\n            if (invalidChipPolls >= 3) autoMHz = 525;\n        } else {\n            invalidChipPolls = 0;\n\n            if (m_chipTempMax > 69.0f) {\n                hotPolls++;\n                coolPolls = 0;\n                if (hotPolls >= 3) {\n                    autoMHz = nerdOctaxeStepDown(autoMHz);\n                    hotPolls = 0;\n                }\n            } else if (m_chipTempMax <= 66.0f) {\n                coolPolls++;\n                hotPolls = 0;\n                if (coolPolls >= 30) {\n                    autoMHz = nerdOctaxeStepUp(autoMHz, configuredMHz);\n                    coolPolls = 0;\n                }\n            } else {\n                hotPolls = 0;\n                coolPolls = 0;\n            }\n        }\n\n        if (chipTempValid) {\n            chipHardCapMHz = nerdOctaxeChipHardCap(m_chipTempMax, chipHardCapMHz);\n        } else if (invalidChipPolls >= 3) {\n            chipHardCapMHz = 525;\n        }\n        vrHardCapMHz = vrTempValid ? nerdOctaxeVrHardCap(vrMax, vrHardCapMHz) : vrHardCapMHz;\n\n        // A hard safety cap also pulls AUTO's state down, so recovery is gradual\n        // instead of jumping straight back to the old frequency after cooling.\n        if (chipHardCapMHz > 0) autoMHz = std::min(autoMHz, chipHardCapMHz);\n        if (vrHardCapMHz > 0) autoMHz = std::min(autoMHz, vrHardCapMHz);\n        autoMHz = std::min(autoMHz, configuredMHz);\n        autoMHz = std::max(autoMHz, 525);\n\n        int runtimeMHz = autoMHz;\n        if (chipHardCapMHz > 0) runtimeMHz = std::min(runtimeMHz, chipHardCapMHz);\n        if (vrHardCapMHz > 0) runtimeMHz = std::min(runtimeMHz, vrHardCapMHz);\n        if (invalidChipPolls >= 3) runtimeMHz = 525;\n\n        // checkAsicFrequencyChanged() runs earlier in this loop. If the user\n        // changes the configured value while AUTO is limiting, re-apply the\n        // calculated runtime value immediately.\n        const bool mustReapply = configuredChanged && runtimeMHz != configuredMHz;\n        if (!m_shutdown && m_board->isInitialized() &&\n            (runtimeMHz != lastRuntimeMHz || mustReapply)) {\n            if (m_board->setAsicFrequency((float) runtimeMHz)) {\n                ESP_LOGW(TAG,\n                         "AUTO governor: chip=%.1fC vr=%.1fC configured=%dMHz auto=%dMHz chipCap=%dMHz vrCap=%dMHz runtime=%dMHz",\n                         m_chipTempMax, vrMax, configuredMHz, autoMHz, chipHardCapMHz, vrHardCapMHz, runtimeMHz);\n                lastRuntimeMHz = runtimeMHz;\n            } else {\n                ESP_LOGE(TAG, "AUTO governor failed to set %dMHz", runtimeMHz);\n            }\n        }\n\n        lastConfiguredMHz = configuredMHz;\n#endif\n\n        // Run fan controller (reads RPM, drives fans, updates overheat flags)'''

if loop_anchor not in src:
    raise SystemExit("Unable to find thermal-governor insertion anchor; upstream changed")
src = src.replace(loop_anchor, loop_replacement, 1)

path.write_text(src)
print("Applied NerdOCTAXE-Gamma adaptive AUTO thermal governor")
